    /** Shows only the parts the slayer tier (1 to 4) reveals; call every frame after resetPose. */
    static void applyTier(ModelPart root, int tier) {
        root.getChild("hips").getChild("shroud_back").getChild("shroud_rags").visible = tier >= 3;
        root.getChild("hips").getChild("waist").getChild("back_stone").visible = tier >= 3;
        root.getChild("hips").getChild("waist").getChild("head").getChild("crown").visible = tier >= 4;
        root.getChild("hips").getChild("waist").getChild("right_arm").getChild("right_forearm").getChild("club").getChild("club_chain2").visible = tier >= 4;
        root.getChild("hips").getChild("waist").getChild("spine").getChild("spine_t3").visible = tier >= 3;
        root.getChild("hips").getChild("waist").getChild("right_arm").getChild("right_arm_t2").visible = tier >= 2;
        root.getChild("hips").getChild("waist").getChild("right_arm").getChild("right_arm_t4").visible = tier >= 4;
        root.getChild("hips").getChild("waist").getChild("right_arm").getChild("right_arm_t3").visible = tier >= 3;
        root.getChild("hips").getChild("waist").getChild("right_arm").getChild("right_forearm").getChild("right_forearm_t2").visible = tier >= 2;
        root.getChild("hips").getChild("waist").getChild("right_arm").getChild("right_forearm").getChild("club").getChild("club_t2").visible = tier >= 2;
        root.getChild("hips").getChild("waist").getChild("left_arm").getChild("left_arm_t3").visible = tier >= 3;
    }
